              "models": "^(gpt-5\\.\\d|gpt-6|gpt-5-codex|gpt-5-pro)",
              "effect": "rejected",
              "note": "reasoningEffort minimal exists only on gpt-5, gpt-5-mini and gpt-5-nano.",
